function discardGuard(){const dialog=$('#dialog');if(!dialog?.querySelector||dialog.querySelector('.discard-guard'))return;const box=document.createElement('div');box.className='discard-guard';box.setAttribute('role','alertdialog');box.setAttribute('aria-modal','true');box.setAttribute('aria-labelledby','discard-title');box.innerHTML=`<div class="discard-card"><span class="discard-icon" aria-hidden="true">!</span><strong id="discard-title">Ungespeicherte Änderungen</strong><p>Du hast an dieser Aufgabe etwas geändert. Beim Schließen gehen die Änderungen verloren.</p><div class="discard-actions">${btn('keep-editing','Weiter bearbeiten')}${btn('discard-task','Verwerfen','danger')}${btn('save-task','Speichern','primary')}</div></div>`;dialog.append(box);box.querySelector('[data-action="keep-editing"]')?.focus();}
function requestCloseModal(){if(taskDirty()){discardGuard();return;}closeModal();}
function closeModal(){if(toastNode.parentElement===$('#dialog'))document.body?.append(toastNode);modalTask=null;modalMode=null;pendingAssets=[];$('#dialog').classList.remove('invitation-print');$('#dialog').close();}
const meeting=()=>db.workshops.find(w=>w.id===workshopId);
const targetYear=()=>meeting()?.examYear||new Date().getFullYear()+1;
let committeeFilters={year:'',specialty:'',query:''};
function committeePeople(names){return names.length?`<ul class="committee-people">${names.map(n=>`<li>${E(n)}</li>`).join('')}</ul>`:'<p class="tiny">Noch keine Mitwirkenden erfasst.</p>';}
function committeePanel(w,s){const c=C.committee(w,s);return `<section class="committee-panel"><div class="row between"><div><p class="eyebrow">Mitwirkende · ${w.examYear}</p><h2>${E(c.name||'Prüfungsausschuss / Arbeitsgruppe')}</h2></div>${btn('edit-committee',c.participants.length?'Mitwirkende bearbeiten':'Mitwirkende erfassen','small',s)}</div>${committeePeople(c.participants)}<p class="tiny">${isGroup?'Die zuständige Stelle pflegt diese Liste. Bitte fehlende Namen dort melden.':'Dokumentiert die Mitarbeit an diesem Termin. Frühere Jahre finden Sie unter „Ausschüsse & Mitwirkende“.'}</p></section>`;}
function committeeForm(s){const w=meeting();if(!w||!w.specialties.includes(s))throw Error('Arbeitsgruppe nicht gefunden.');const c=C.committee(w,s);openModal('Mitwirkende · '+s,`<p class="eyebrow">Prüfungsjahr ${w.examYear} · ${E(w.title)}</p><p>Wer gestaltet die Prüfungen in dieser Gruppe? Tragen Sie alle beteiligten Personen ein, auch wenn mehrere Personen an einem Gerät arbeiten.</p><div class="field"><label for="committee-name">Ausschussbezeichnung (optional)</label><input id="committee-name" maxlength="160" value="${E(c.name)}" placeholder="z. B. Prüfungsausschuss Gemüsebau Freiburg"></div><div class="field"><label for="committee-members">Mitwirkende Personen</label><textarea id="committee-members" rows="7" placeholder="Vorname Nachname&#10;Vorname Nachname">${E(c.participants.join('\n'))}</textarea><p class="tiny">Eine Person je Zeile. Bitte vollständige Namen verwenden.</p></div><p class="tiny">Die Angaben bleiben beim Termin und Prüfungsjahr gespeichert. Bei Korrekturen bleibt die vorherige Liste in der Historie erhalten. Diese Liste dokumentiert die Mitarbeit, nicht die förmliche Berufung.</p>`,btn('close','Abbrechen')+btn('save-committee','Mitwirkende speichern','primary',s));}
function saveCommittee(s){C.saveCommittee(db,workshopId,s,{name:$('#committee-name').value,participants:$('#committee-members').value.split(/\r?\n/).map(n=>n.trim()).filter(Boolean)});changed();closeModal();render();toast('Mitwirkende für diese Gruppe und dieses Prüfungsjahr übernommen.');}
function committeeRows(){return C.committeeHistory(db,committeeFilters);}
function committeesView(){const rows=committeeRows(),years=[...new Set(db.workshops.map(w=>String(w.examYear)))].sort().reverse();return `<p class="eyebrow">Dokumentation der Prüfungsvorbereitung</p><h1>Ausschüsse & Mitwirkende</h1><p class="intro">Wer hat in welchem Jahr die Prüfungen gestaltet? Die Listen gehören zum jeweiligen Termin und bleiben nach dem Schließen der Gruppenzugänge erhalten.</p><div class="panel committee-filters"><div class="field"><label for="committee-query">Person oder Ausschuss suchen</label><input id="committee-query" type="search" value="${E(committeeFilters.query)}" placeholder="Name, Ausschuss oder Termin"></div><div class="field"><label for="committee-year">Prüfungsjahr</label><select id="committee-year">${options(years,committeeFilters.year,'Alle Jahre')}</select></div><div class="field"><label for="committee-specialty">Fachrichtung</label><select id="committee-specialty">${options(C.specialties,committeeFilters.specialty,'Alle Fachrichtungen')}</select></div><div class="toolbar">${btn('filter-committees','Suchen','primary')}${btn('reset-committees','Zurücksetzen')}</div></div><div class="row between section-heading"><p>${rows.length} ${rows.length===1?'Gruppe':'Gruppen'}${committeeFilters.query?' · Suche berücksichtigt auch frühere Einträge':''}</p>${btn('export-committees','Liste als CSV exportieren','small')}</div><div class="committee-history">${rows.map(r=>`<article class="panel"><div class="row between"><div><p class="eyebrow">Prüfungsjahr ${r.examYear} · ${E(r.specialty)}</p><h2>${E(r.name||'Prüfungsausschuss / Arbeitsgruppe')}</h2><p class="tiny">${E(r.workshopTitle)} · Vorbereitung: ${r.meetingDate?E(r.meetingDate.split('-').reverse().join('.')):'Datum offen'}</p></div>${btn('committee-open','Gruppe öffnen','small',JSON.stringify([r.workshopId,r.specialty]))}</div>${committeePeople(r.participants)}${r.updatedAt?`<p class="tiny">Letzter Eintrag: ${E(new Date(r.updatedAt).toLocaleString('de-DE'))}</p>`:''}${r.revisions.length?`<details class="committee-revisions"><summary>Frühere Einträge (${r.revisions.length})</summary><p class="tiny">Frühere Fassungen der Liste. Sie können Korrekturen enthalten und sind kein Anwesenheitsnachweis.</p>${r.revisions.slice().reverse().map(v=>`<div><strong>${E(v.name||'Ohne Ausschussbezeichnung')}</strong><span class="tiny"> · erfasst ${E(new Date(v.recordedAt).toLocaleString('de-DE'))}</span>${committeePeople(v.participants)}</div>`).join('')}</details>`:''}</article>`).join('')||'<div class="panel"><h2>Keine passenden Gruppen</h2><p>Wählen Sie andere Filter oder legen Sie einen Termin an. Mitwirkende erfassen Sie direkt bei der jeweiligen Arbeitsgruppe.</p></div>'}</div>`;}
function committeeCsv(rows){const cell=v=>'"'+String(v??'').replace(/^[\s]*[=+@-]/,m=>"'"+m).replace(/"/g,'""')+'"',out=[['Prüfungsjahr','Termin','Datum','Fachrichtung','Ausschuss','Person','Fassung','Erfasst am']];for(const r of rows){for(const v of [{name:r.name,participants:r.participants,recordedAt:r.updatedAt,current:true},...r.revisions])for(const person of v.participants.length?v.participants:[''])out.push([r.examYear,r.workshopTitle,r.meetingDate,r.specialty,v.name,person,v.current?'Aktuell':'Frühere Fassung',v.recordedAt]);}return '\uFEFF'+out.map(row=>row.map(cell).join(';')).join('\r\n');}
async function exportCommittees(){if(isGroup)throw Error('Nur für die zuständige Stelle.');if(online){await flush();await online.request('/api/export');}download('Ausschuesse-und-Mitwirkende.csv',committeeCsv(committeeRows()),'text/csv;charset=utf-8');}
function fwTopicGuide(t,editable=false,context=t.pattern?L.examContext(t):L.projectContext(db,t)){if(t.examType!=='FW_AP')return '';return `<details class="fw-topic-guide"><summary>Hauptaufgabengebiete & Unteraufgaben verstehen</summary><p>Die bereitgestellte Fachwerker-Liste nennt sieben Hauptaufgabengebiete. Sie beschreibt mögliche Inhalte. Die verbindlichen vier Aufgaben und 180 Minuten stammen aus § 11 GBFWVO. Wählen Sie Tätigkeiten, die zur Fachrichtung passen. Die Beispiele gelten fachrichtungsübergreifend.</p>${L.categories(db,t.examType,t.specialty,context).map(c=>`<details><summary>${E(c.label)}</summary>${L.fachwerkerTopics(context,c.id).length?`<div class="fw-topic-examples">${L.fachwerkerTopics(context,c.id).map((name,n)=>editable?btn('fw-topic',E(name),'small',JSON.stringify([c.id,n])):`<span>${E(name)}</span>`).join('')}</div>`:'<p class="tiny">In der bereitgestellten Liste sind hierzu keine Unteraufgaben angegeben.</p>'}</details>`).join('')}<p class="tiny">Quelle: AP Fachwerkeraufgaben, Seiten 1–2. „Ernten“ gehört zu „Durchführen von Arbeiten an und mit der Pflanze“. ${editable?'Ein Beispiel anklicken: Es wird als Stichwort übernommen und das Hauptaufgabengebiet ausgewählt. Den vollständigen Arbeitsauftrag schreiben Sie anschließend selbst.':''}</p></details>`;}
function useFwTopic(value){if(modalTask?.examType!=='FW_AP')return;const [id,n]=JSON.parse(value),topic=L.fachwerkerTopics(taskContext(modalTask),id)[n];if(!topic)throw Error('Unteraufgabe nicht gefunden.');const box=$$('[data-planning-category]').find(x=>x.value===id);if(box)box.checked=true;modalMode.categoryEdited=true;resetWritingReview();if($('#task-materials-confirm'))$('#task-materials-confirm').checked=false;modalMode.materialsConfirmed=false;const tags=$('#task-tags'),values=parseTags(tags.value);if(!values.some(x=>x.toLocaleLowerCase('de')===topic.toLocaleLowerCase('de')))values.push(topic);tags.value=formatTags(values);if(!$('#task-title').value.trim())$('#task-title').value=topic;toast('Hauptaufgabengebiet ausgewählt und Stichwort übernommen. Arbeitsauftrag jetzt ausformulieren.');}
function reportbookPolicyNotice(e){return `<div id="reportbook-policy-notice">${C.reportbookIssues(e).length?`<div class="callout warning"><strong>Veralteter Hilfsmittelhinweis in dieser Prüfung</strong><p>Ab Prüfungsjahr 2026 ist das Berichtsheft nicht mehr zugelassen. In diesem Entwurf steht noch eine frühere Erlaubnis. Entferne den Hinweis vor dem Export; die Originale im Archiv bleiben erhalten.</p>${btn('clean-reportbook','Veralteten Berichtshefthinweis entfernen','small')}</div>`:''}</div>`;}
function cleanCurrentReportbook(){const e=editableExam();if(C.cleanReportbook(e)){changed();render();if($('#dialog').open)paperCheck();toast('Veralteter Berichtshefthinweis aus diesem Entwurf entfernt. Die Originale bleiben erhalten.');}}
const scopedExams=()=>db.exams.filter(e=>!e.deletedAt&&e.examType===type&&e.specialty===fr&&(!workshopId||e.workshopId===workshopId));
function meetingPicker(){if(isGroup)return '';return db.workshops.length?`<div class="meeting-picker"><label for="meeting-select">Termin</label><select id="meeting-select">${db.workshops.map(w=>`<option value="${E(w.id)}" ${w.id===workshopId?'selected':''}>${E(w.title)} · Prüfungsjahr ${w.examYear}</option>`).join('')}</select>${btn('edit-workshop','Termin bearbeiten','small')}${btn('new-workshop','+ Weiterer Termin','small')}</div>`:'';}
function dashboardSteps(){return `<div class="workflow-steps" aria-label="Ablauf der Prüfungsvorbereitung">${[
 ['01','Termin vorbereiten','Prüfungsjahr und Fachrichtungen festlegen.','dashboard'],
 ['02','Gruppen einladen','Je Fachrichtung ein temporärer QR- oder Link-Zugang.','access'],
 ['03','Prüfungen erarbeiten','Zwischen- und Abschlussprüfung getrennt zusammenstellen.','groups'],
 ['04','Ergebnisse prüfen','Aufgaben, Punkte und Lösungen prüfen und exportieren.','results']
].map(([n,title,text,r])=>`<button data-route="${r}" aria-current="${route===r?'page':'false'}" class="workflow-step ${route===r?'selected':''}"><span class="step-number">${n}</span><strong>${title}</strong><span>${text}</span>${r==='access'&&!online?'<small>Zugänge noch nicht verfügbar</small>':''}</button>`).join('')}</div>`;}
function adminView(){const tiles=[['groups','users','Termin & Arbeitsgruppen','Prüfungsjahr, Fachrichtungen und Arbeitsbereiche'],['access','qr','Zugänge & QR-Codes','Arbeitsgruppen einladen und Geräte freigeben'],['committees','users','Ausschüsse & Mitwirkende','Mitwirkende je Jahr und Fachrichtung'],['settings','sliders','Themenvorgaben','Themen und Grundeinstellungen je Prüfungsart'],['scope','library','Aufgabenbestand & Muster','Aufgabenbank, Ausführungen und Prüfungsmuster'],['import','upload','Import & Quellen','Word-Dateien einlesen, Originale ansehen'],['results','checkFile','Alle Prüfungen & Papierkorb','Prüfungen aller Termine, gelöschte Entwürfe']];return `<p class="eyebrow">Zuständige Stelle</p><h1>Einstellungen</h1><p class="intro">Alles, was selten gebraucht wird.</p><div class="settings-hub">${tiles.map(([r,i,t,d])=>`<button class="settings-tile" data-route="${r}"><span class="nav-icon">${I.icon(i)}</span><span><strong>${t}</strong><small>${d}</small></span></button>`).join('')}${forbidden('backup')?'':`<button class="settings-tile" data-action="backup"><span class="nav-icon">${I.icon('download')}</span><span><strong>Sicherung</strong><small>Gesamten Stand als Datei sichern</small></span></button>`}</div>`;}
function dashboardView(){const w=meeting();if(!w)return `<p class="eyebrow">Zuständige Stelle</p><h1>Start</h1>${meetingPicker()}<div class="start-panel"><h2>Termin vorbereiten</h2><p>Prüfungsjahr und Fachrichtungen festlegen. Danach stehen die Arbeitsgruppen bereit.</p>${btn('new-workshop','Termin vorbereiten','primary')}</div>`;
 const es=C.workshopExams(db,w.id),waiting=es.filter(e=>examProgress(e).kind==='wait').length,types=['ZP','AP','FW_AP'].filter(t=>w.specialties.some(s=>C.allowedExamTypes(w,s).includes(t)||es.some(e=>e.examType===t&&e.specialty===s)));
 const cell=(s,t)=>{const list=es.filter(e=>e.specialty===s&&e.examType===t);if(list.length)return list.map(e=>{const p=examProgress(e);return `<button class="status-pill is-${p.kind}" data-action="select-exam" data-id="${E(e.id)}" title="${E(e.title)}">${E(p.status)}</button>`;}).join('');return C.examTypesFor(s).includes(t)&&C.allowedExamTypes(w,s).includes(t)?`<button class="status-pill is-none" data-action="open-group" data-id="${E(s)}">Nicht begonnen</button>`:'<span class="status-none">–</span>';};
 return `<div class="start-head"><div><p class="eyebrow">Zuständige Stelle</p><h1>Prüfungsjahr ${w.examYear}</h1><p class="intro">${waiting?`${waiting} ${waiting===1?'Prüfung wartet':'Prüfungen warten'} auf eure Freigabe.`:'Ein Klick auf ein Feld öffnet die Prüfung.'}</p></div><div class="start-head-actions"><button data-route="access">${I.icon('qr')}<span>Arbeitsgruppen einladen</span></button>${btn('export-meeting','Alles ausgeben (ZIP)','primary')}</div></div>${meetingPicker()}
 <div class="status-table-wrap"><table class="status-table"><thead><tr><th scope="col">Fachrichtung</th>${types.map(t=>`<th scope="col">${E(C.examTypeLabel(t))}</th>`).join('')}<th scope="col">Arbeitsgruppe</th></tr></thead><tbody>${w.specialties.map(s=>`<tr><th scope="row"><button class="link" data-action="open-group" data-id="${E(s)}">${E(s)}</button></th>${types.map(t=>`<td>${cell(s,t)}</td>`).join('')}<td class="tiny">${C.committee(w,s).participants.length} Mitwirkende · ${online?E(accessStatus(w.id)):'offline'}</td></tr>`).join('')}</tbody></table></div><p class="tiny">Grün = freigegeben, Orange = wartet auf Freigabe, Grau = in Arbeit oder nicht begonnen.</p>`;}
function groupCards(){const w=meeting();if(!w)return '<div class="panel"><h2>Zuerst einen Termin vorbereiten</h2><p>Danach stehen die Arbeitsbereiche bereit.</p>'+btn('new-workshop','Termin vorbereiten','primary')+'</div>';return `<div class="group-grid compact-groups">${w.specialties.map(s=>{const es=C.workshopExams(db,w.id,s),people=C.committee(w,s).participants;return `<article class="group-card"><div class="group-card-top"><h3>${E(s)}</h3><span class="badge gray">${online?accessStatus(w.id):'Zugang noch nicht eingerichtet'}</span></div><p class="tiny group-track-line">${C.examTypesFor(s).filter(t=>C.allowedExamTypes(w,s).includes(t)||es.some(e=>e.examType===t)).map(t=>E(C.examTypeLabel(t))+' · '+es.filter(e=>e.examType===t).length).join('<br>')}</p><div class="group-card-actions">${btn('open-group','Arbeitsbereich öffnen →','primary',s)}${btn('invitation','QR-Code & Zugang','small',s)}</div>${uiPanel('group-'+w.id+'-'+s,`Mitwirkende <span class="tiny">${people.length?people.length+' erfasst':'noch offen'}</span>`,committeePeople(people)+btn('edit-committee','Mitwirkende bearbeiten','small',s),'group-more')}</article>`;}).join('')}</div>`;}

function groupsView(){return `<p class="eyebrow">3 · Prüfungen erarbeiten</p><h1>Arbeitsbereiche der Fachrichtungen</h1><p class="intro">Jede Fachrichtung arbeitet an ihren Zwischen- und Abschlussprüfungen. Sie öffnen die Arbeitsbereiche hier als zuständige Stelle.</p>${meetingPicker()}<div class="toolbar"><button data-route="committees">Ausschüsse & Mitwirkende aller Jahre →</button></div>${groupCards()}`;}
// Only what really has to be done. Point proposals, source hints, material proposals and the professional review
// are confirmed by the release itself and are never listed as open points.
function openTodos(e){try{return R.inspect(e).issues.filter(x=>x!=='Bereits dokumentierte Prüfungen bleiben unverändert.');}catch(error){return C.readiness(e).issues;}}
function examProgress(e){const c=L.structureCoverage(e),oral=C.oralStatus(e),ready=C.readiness(e),steps=[];if(c?.profile.themeCount)steps.push([!L.themeSelectionIssue(e),'Themen wählen']);steps.push([c?c.total===c.profile.totalTasks:e.items.length>0,c?`Aufgabe ${Math.min(c.total+1,c.profile.totalTasks)} wählen`:'Aufgaben wählen']);if(oral.required)steps.push([!!e.oralItem,'Mündliche Aufgabe wählen']);if(c)steps.push([!c.unknownMinutes&&c.total>=c.profile.totalTasks&&(c.profile.exactMinutes!=null?c.minutes===c.profile.exactMinutes:c.minutes<=c.profile.maxMinutes),'Zeiten prüfen']);steps.push([!openTodos(e).length,'Offene Angaben ergänzen']);
 const done=steps.filter(x=>x[0]).length,released=e.releaseReview?.contentKey===C.examReviewKey(e)&&ready.ready,status=e.status==='used'?'Eingesetzt':released?'Freigegeben':e.submittedAt?'Wartet auf Freigabe':done?`In Arbeit · ${done} von ${steps.length}`:'Begonnen';return {done,total:steps.length,next:steps.find(x=>!x[0])?.[1]||'',status,kind:e.status==='used'||released?'done':e.submittedAt?'wait':'work'};}
function examCard(e){const p=examProgress(e);return `<article class="start-card"><div class="start-card-top"><span class="badge ${e.examType==='AP'?'blue':''}">${E(C.examTypeLabel(e.examType))}</span><span class="start-status is-${p.kind}">${E(p.status)}</span></div><h2>${E(e.title)}</h2>${submissionBadge(e)}<div class="start-progress" role="progressbar" aria-valuemin="0" aria-valuemax="${p.total}" aria-valuenow="${p.done}" aria-label="Fortschritt"><i style="width:${Math.round(p.done/p.total*100)}%"></i></div><p class="start-next">${p.next&&p.kind==='work'?'Als Nächstes: '+E(p.next):p.kind==='wait'?'Die zuständige Stelle sieht die Prüfung durch.':p.kind==='done'?'Fertig.':'Alles vollständig – jetzt fertigstellen.'}</p><div class="start-actions">${btn('select-exam',e.status==='used'?'Ansehen':'Weiterarbeiten','primary',e.id)}${e.internalNotes?.trim()?internalNotesButton(e,'link'):''}</div></article>`;}
function groupView(){const w=meeting();if(!w||!w.specialties.includes(fr))return groupsView();const es=C.workshopExams(db,w.id,fr),types=C.examTypesFor(fr).filter(t=>C.allowedExamTypes(w,fr).includes(t)||es.some(e=>e.examType===t));
 const cards=types.flatMap(t=>{const drafts=es.filter(e=>e.examType===t),allowed=C.allowedExamTypes(w,fr).includes(t),empty=!L.scoped(db,t,fr).length;return drafts.length?drafts.map(examCard):allowed?[`<article class="start-card is-new"><div class="start-card-top"><span class="badge ${t==='AP'?'blue':''}">${E(C.examTypeLabel(t))}</span><span class="start-status">Noch nicht begonnen</span></div><h2>${E(C.examTypeLabel(t))} ${w.examYear}</h2><p class="start-next">${empty?'Für diese Prüfungsart gibt es noch keine Aufgaben. Ihr könnt eigene schreiben.':'Themen und Vorschläge stehen gleich bereit.'}</p><div class="start-actions">${btn('track-new','Prüfung beginnen','primary',t)}</div></article>`]:[];}).join('');
 const more=types.filter(t=>C.allowedExamTypes(w,fr).includes(t)&&es.some(e=>e.examType===t)).map(t=>btn('track-new','Weitere '+C.examTypeLabel(t)+' anlegen','link',t)).join('');
 return `<p class="eyebrow">Prüfungsjahr ${w.examYear}</p><h1>${E(fr)}</h1><p class="intro">${isGroup?'Eure Prüfungen: öffnen, weiterarbeiten, fertigstellen.':'Prüfungen dieser Arbeitsgruppe.'}</p><div class="start-cards">${cards||'<p class="empty-track">Für diesen Termin ist keine Prüfung vorgesehen.</p>'}</div><p class="start-links">${more}${isGroup?'':btn('invitation','QR-Code & Zugang','link',fr)}${isGroup?'':'<button class="link" data-route="dashboard">Alle Fachrichtungen</button>'}</p>${committeePanel(w,fr)}`;}
function workshopForm(edit=false){const w=edit?meeting():null;openModal(w?'Termin bearbeiten':'Termin anlegen',`<p class="intro">Lege fest, welche Gruppen teilnehmen und welche Prüfungen sie in diesem Termin erstellen sollen. Änderungen an der Auswahl löschen keine vorhandenen Entwürfe.</p><div class="field"><label for="workshop-title">Name des Termins</label><input id="workshop-title" value="${E(w?.title||'Aufgabenerstellung '+(new Date().getFullYear()+1))}"></div><div class="grid2"><div class="field"><label for="workshop-year">Prüfungsjahr</label><input id="workshop-year" type="number" min="1900" max="2200" step="1" value="${w?.examYear||new Date().getFullYear()+1}"></div><div class="field"><label for="workshop-date">Termin (optional)</label><input id="workshop-date" type="date" value="${E(w?.meetingDate||'')}"></div></div><h3>Arbeitsbereiche und vorgesehene Prüfungen</h3>${FR.map(s=>`<fieldset class="workshop-scope"><label class="check"><input type="checkbox" data-workshop-specialty value="${E(s)}" ${!w||w.specialties.includes(s)?'checked':''}><strong>${E(s)}</strong></label><div class="workshop-exam-types">${C.examTypesFor(s).map(t=>`<label class="check"><input type="checkbox" data-workshop-exam-type data-specialty="${E(s)}" value="${t}" ${(!w||C.allowedExamTypes(w,s).includes(t))?'checked':''}>${E(C.examTypeLabel(t))}</label>`).join('')}</div></fieldset>`).join('')}<p class="tiny">Nur angekreuzte Prüfungsarten werden zur Neuerstellung angeboten. Die Auswahl öffnet noch keine externen Zugänge; dafür gibt es „Gruppen & Einladungen“.</p>`,btn('close','Abbrechen')+btn('save-workshop',w?'Änderungen speichern':'Termin & Arbeitsbereiche anlegen','primary',w?.id||''));}
function saveWorkshop(id){const w={...C.clone(db.workshops.find(w=>w.id===id)||{}),id:id||C.id('workshop'),title:$('#workshop-title').value.trim(),examYear:Number($('#workshop-year').value),meetingDate:$('#workshop-date').value,specialties:$$('[data-workshop-specialty]:checked').map(x=>x.value)};const fields=$$('[data-workshop-exam-type]');w.examTypesBySpecialty=Object.fromEntries(w.specialties.map(s=>[s,fields.length?fields.filter(x=>x.dataset.specialty===s&&x.checked).map(x=>x.value):C.allowedExamTypes(w,s)]));C.saveWorkshop(db,w);workshopId=w.id;examId=null;type=fr=category='';route='dashboard';changed();closeModal();render();toast('Termin gespeichert. Die Arbeitsbereiche sind vorbereitet.');}
function invitation(s){if(online)return showInvitation(s);const w=meeting();if(!w)throw Error('Bitte zuerst einen Termin anlegen.');openModal('Gruppenzugang · '+s,`<p class="eyebrow">${E(w.title)} · Prüfungsjahr ${w.examYear}</p><div class="invitation-state"><span aria-hidden="true">⌁</span><h2>QR-Code noch nicht verfügbar</h2><p>Ein sicherer Gruppenzugang kann erst erstellt werden, wenn der Anmeldedienst angeschlossen ist.</p></div><div class="callout warning"><strong>Noch keine Einladung versenden</strong>Das Passwort der zuständigen Stelle öffnet den gesamten Bestand. Es darf nicht als Gruppenpasswort oder QR-Code verteilt werden.</div><h3>So soll der Zugang anschließend funktionieren</h3><ol class="track-guide"><li>Sie geben die Sitzung frei und zeigen den QR-Code oder teilen den Gruppenlink.</li><li>Die Gruppe landet direkt bei ${E(s)} mit Zwischen- und Abschlussprüfung ${w.examYear}.</li><li>Sie schließen die Sitzung; weitere Zugriffe werden serverseitig gesperrt.</li></ol><p class="tiny">Freigabe, Ablauf und Exportrechte sind in dieser Testversion noch nicht durchgesetzt. Bereits angefertigte Kopien oder Bildschirmaufnahmen lassen sich nicht zurückholen.</p>`,btn('close','Schließen')+'<button disabled>QR-Code anzeigen / Link kopieren</button>');}
let trashPick=null,lastTrashed=[];
// Drafts the coordinating body may delete here: not in the trash and never used in an exam.
const deletableExam=e=>!e.deletedAt&&e.status!=='used'&&!db.uses.some(u=>u.examId===e.id);
function visibleResultExams(){const w=meeting();return [...(w?C.workshopExams(db,w.id):[]),...db.exams.filter(e=>!e.deletedAt&&(!w||e.workshopId!==w.id))];}
// Trash button, multi-select bar and an undo strip right after deleting.
function trashTools(visible){
 lastTrashed=lastTrashed.filter(id=>db.exams.some(e=>e.id===id&&e.deletedAt));
 const del=visible.filter(deletableExam),empty=del.filter(e=>!e.items.length),inBin=db.exams.filter(e=>e.deletedAt).length;
 if(trashPick)for(const id of [...trashPick])if(!del.some(e=>e.id===id))trashPick.delete(id);
 const head=`<div class="trash-head">${btn('show-trash','Papierkorb ('+inBin+')','small')}${del.length?btn('trash-pick-mode',trashPick?'Auswahl beenden':'Mehrere Entwürfe löschen …','small'):''}</div>`;
 const undo=lastTrashed.length?`<div class="trash-undo" role="status">${I.icon('trash')}<span>${lastTrashed.length===1?`„${E(db.exams.find(e=>e.id===lastTrashed[0])?.title||'Entwurf')}“ liegt jetzt im Papierkorb.`:`${lastTrashed.length} Entwürfe liegen jetzt im Papierkorb.`}</span>${btn('trash-undo','Rückgängig','small')}</div>`:'';
 const bar=trashPick?`<div class="trash-bar" role="region" aria-label="Entwürfe zum Löschen auswählen"><strong>${trashPick.size} von ${del.length} ausgewählt</strong><div class="toolbar">${empty.length?btn('trash-pick-empty',`Leere Entwürfe (${empty.length})`,'small'):''}${btn('trash-pick-all',`Alle (${del.length})`,'small')}${trashPick.size?btn('trash-pick-none','Auswahl aufheben','small'):''}${trashPick.size?btn('trash-selected',`In den Papierkorb (${trashPick.size})`,'danger small'):''}</div></div>`:'';
 return head+undo+bar;
}
function resultsView(){const w=meeting(),es=w?C.workshopExams(db,w.id):[],others=db.exams.filter(e=>!e.deletedAt&&(!w||e.workshopId!==w.id));return `<p class="eyebrow">4 · Ergebnisse prüfen</p><h1>Prüfungen & Ergebnisse</h1>${trashTools([...es,...others])}<p class="intro">Öffnen Sie einen Entwurf, kontrollieren Sie Kategorien, Punkte und Lösungen und erstellen Sie anschließend die Teilnehmer- und Prüferfassung.</p>${meetingPicker()}${w?`<h2>${E(w.title)} · ${w.examYear}</h2>${es.some(e=>C.examEntries(e).length)?`<div class="meeting-export">${btn('export-meeting','Alle Prüfungen dieses Termins exportieren (ZIP)','primary',w.id)}<p class="tiny">Ein Ordner je Fachrichtung, darin je Prüfung Prüfungsbogen, Lösung &amp; Bewertung, Materialliste, interne Bemerkungen, Zeitplan und Anlagen – dazu eine Materialübersicht je Fachrichtung.</p></div>`:''}${resultRows(es)}`:''}${others.length?`<h2 class="section-title">${w?'Weitere und bisherige Prüfungen':'Alle bisherigen Prüfungen'}</h2>${resultRows(others)}`:!w?'<div class="panel empty">Noch keine Prüfungen vorhanden. Beginnen Sie auf der Übersicht mit einem Termin.</div>':''}`;}
function resultRows(es){return es.length?es.map(e=>{const r=C.readiness(e),w=db.workshops.find(w=>w.id===e.workshopId),pickable=!!trashPick&&deletableExam(e),picked=pickable&&trashPick.has(e.id);return `<article class="result-row panel${picked?' is-picked':''}">${pickable?`<button class="pick-toggle" data-action="trash-pick" data-id="${E(e.id)}" aria-pressed="${picked}" aria-label="${E(e.title)} ${picked?'abwählen':'zum Löschen auswählen'}">${I.icon('check')}</button>`:''}<div class="result-main"><div class="tags"><span class="badge ${e.examType==='AP'?'blue':''}">${C.examTypeLabel(e.examType)}</span><span class="badge ${r.ready?'':'amber'}">${e.status==='used'?'Einsatz dokumentiert':r.ready?'Freigaben vollständig':'Bearbeitung offen'}</span></div><h3>${E(e.title)}</h3>${submissionBadge(e)}<p class="tiny">${E(e.specialty)} · ${e.examYear||'Prüfungsjahr offen'} · ${e.items.length} Aufgaben · ${E(w?.title||'Noch keinem Termin zugeordnet')}</p></div><div class="toolbar">${e.internalNotes?.trim()?internalNotesButton(e):''}${deletableExam(e)&&!trashPick?btn('trash-row','Löschen','small quiet-danger',e.id):''}${btn('select-exam','Prüfen / weiterarbeiten →','primary',e.id)}</div></article>`;}).join(''):'<div class="panel empty">Für diesen Termin wurden noch keine Prüfungen angelegt. Öffnen Sie einen Fachrichtungsbereich unter „Arbeitsgruppen“.</div>';}

let settingsType='ZP',settingsSpecialty='Baumschule';
function settingsScope(){return {examType:settingsType,specialty:settingsSpecialty};}
function settingsRecord(){const scope=settingsScope(),id=L.settingsId(scope),exact=db.settings?.find(r=>r.id===id);if(exact)return C.clone(exact);const inherited=L.settingsFor(db,scope);if(!inherited)return {id,schemaVersion:1,revision:0,...scope,categories:[],defaults:{}};const definitions=new Map(L.resolveCatalog(db,scope).map(c=>[c.id,c]));return {...C.clone(inherited),...scope,id,revision:0,categories:inherited.categories.filter(c=>definitions.has(c.id)).map(c=>({...C.clone(c),hidden:definitions.get(c.id).hidden}))};}
function saveSettingsRecord(record){if(isGroup)throw Error('Grundeinstellungen sind der zuständigen Stelle vorbehalten.');const previous=db.settings?.find(r=>r.id===record.id);record.revision=(previous?.revision||0)+1;L.checkSettings(record,previous,db);const next=C.clone(db);next.settings=(next.settings||[]).filter(x=>x.id!==record.id).concat(record);C.validate(next);db.settings=next.settings;changed();closeModal();render();toast('Grundeinstellungen übernommen. Bestehende Prüfungen behalten ihren eigenen Stand.');}
function zwischenpruefungInfo(scope){const info=L.zwischenpruefungScopeInfo?.(scope);return info?`<details class="workflow-note"><summary>Grundlage der Themenauswahl</summary><p>${E(info.text)}</p>${info.url?`<p class="tiny"><a href="${E(info.url)}" target="_blank" rel="noopener noreferrer">${E(info.reference)}</a></p>`:''}</details>`:'';}
function settingsView(){
 const scope=settingsScope(),record=settingsRecord(),defs=L.resolveCatalog(db,scope),active=defs.filter(c=>!c.hidden),hidden=defs.filter(c=>c.hidden),rule=L.regulationProfile(scope),specialties=settingsType==='FW_AP'?C.fachwerkerSpecialties:C.specialties;
 const row=c=>`<article class="setting-category ${c.hidden?'is-hidden':''}"><div><h3>${E(c.label)}</h3><p class="tiny">${c.origin==='custom'?'Eigene Kategorie':'Standardthema'}${c.help?' · '+E(c.help):''}</p>${c.topics?.length?`<details><summary>${c.topics.length} Beispiele / Unteraufgaben</summary><p class="tiny">${c.topics.map(E).join(' · ')}</p></details>`:''}</div><div class="setting-actions">${btn('settings-category', 'Bearbeiten','small',c.id)}${c.hidden?btn('settings-restore','Wieder anbieten','small',c.id):btn('settings-remove','Entfernen','small danger',c.id)}</div></article>`;
 return `<p class="eyebrow">Zuständige Stelle</p><h1>Grundeinstellungen</h1><p class="intro">Hier legst du fest, welche Themen und Standardangaben für neue Prüfungen angeboten werden. Bereits angelegte Prüfungen behalten ihren gespeicherten Stand.</p><div class="panel settings-scope"><div class="field"><label for="settings-type">Prüfungsart</label><select id="settings-type">${typeOptions(settingsType)}</select></div><div class="field"><label for="settings-specialty">Geltungsbereich</label><select id="settings-specialty">${options(specialties,settingsSpecialty)}</select></div></div>${zwischenpruefungInfo(scope)}<div class="settings-layout"><section class="panel"><div class="row between"><div><h2>${settingsType==='ZP'?'Generalthemen':'Themen & Kategorien'}</h2><p class="tiny">${active.length} angeboten · ${hidden.length} ausgeblendet</p></div>${btn('settings-category','Thema hinzufügen','primary')}</div><p class="tiny">Namen, Erläuterungen und Reihenfolge sind bearbeitbar. Entfernte Standardthemen werden für neue Prüfungen ausgeblendet. Ihre bisherigen Aufgaben und alten Prüfungen bleiben erhalten.</p><div class="settings-categories">${active.map(row).join('')||'<p>Derzeit wird kein Thema angeboten. Füge ein Thema hinzu oder stelle eines wieder her.</p>'}</div>${hidden.length?`<details class="settings-retired"><summary>Ausgeblendete Themen (${hidden.length})</summary>${hidden.map(row).join('')}</details>`:''}</section><aside><section class="panel"><h2>Standardangaben</h2><p class="tiny">Diese Angaben werden beim Anlegen einer Prüfung übernommen und können dort angepasst werden.</p><label for="settings-title">Prüfungstitel</label><input id="settings-title" maxlength="300" value="${E(record.defaults?.title||'')}" placeholder="Praktische {pruefungsart} {jahr}"><p class="tiny">Platzhalter: {jahr}, {fachrichtung}, {pruefungsart}</p><label for="settings-notes">Hinweise für Teilnehmende</label><textarea id="settings-notes" rows="5" maxlength="20000">${E(record.defaults?.notes||'')}</textarea><p class="tiny">Diese Hinweise erscheinen auf dem Deckblatt frei gestalteter Prüfungen. Bei Originalvorlagen ohne Deckblatt bitte die Hinweise direkt auf der Originalseite bearbeiten. Vertrauliche Abstimmungen gehören in die internen Bemerkungen.</p><label for="settings-minutes">Organisatorische Zielzeit (optional, Minuten)</label><input id="settings-minutes" type="number" min="0" max="${settingsType==='AP'?300:1440}" value="${record.defaults?.targetMinutes??''}"><p class="tiny">Planungshilfe für den Termin; keine Änderung der gesetzlichen Höchstzeit oder der Aufgabenzeiten.</p>${btn('settings-save-defaults','Standardangaben speichern','primary wide')}</section><section class="panel"><h2>Was bleibt verbindlich?</h2><p>${rule?'Die Abschlussprüfung enthält fünf komplexe praktische Aufgaben. Die Mindestanzahlen ihrer Prüfungsbereiche und die Höchstzeit von 300 Minuten bleiben geschützt. Eigene Kategorien benötigen eine fachlich begründete Bereichszuordnung.':settingsType==='ZP'?'Je ausgewähltem Generalthema ist höchstens eine Einzelaufgabe erlaubt. Kombinationsaufgaben werden nicht angeboten. Insgesamt sind genau drei praktische Aufgaben aus drei unterschiedlichen Generalthemen und höchstens 180 Minuten vorgesehen.':'Die Fachwerker-Abschlussprüfung enthält genau vier praktische Aufgaben in insgesamt 180 Minuten. Die Themen sind freiwillige Suchfilter.'}</p>${paperInfo('Änderungen und alte Prüfungen','Neue Prüfungen speichern die geltenden Themen und Bezeichnungen als eigenen Stand. Umbenennen oder Entfernen verändert deshalb weder alte Prüfungen noch den ursprünglichen Wortlaut der Fragenbank.')}</section></aside></div>`;
}
function wireSettings(){for(const [id,fn]of [['settings-type',v=>{settingsType=v;if(v==='FW_AP'&&!C.fachwerkerSpecialties.includes(settingsSpecialty))settingsSpecialty=C.fachwerkerSpecialties[0];}],['settings-specialty',v=>settingsSpecialty=v]])$('#'+id)?.addEventListener('change',ev=>{fn(ev.target.value);render();});}
function settingsCategoryDialog(id){if(isGroup)return;const defs=L.resolveCatalog(db,settingsScope()),c=defs.find(x=>x.id===id);openModal(c?'Thema bearbeiten':'Thema hinzufügen',`<p class="tiny">Die Kennung bleibt intern stabil. Eine neue Bezeichnung verändert keine vorhandenen Aufgabenformulierungen.</p><label for="setting-category-label">Bezeichnung *</label><input id="setting-category-label" maxlength="240" value="${E(c?.label||'')}"><label for="setting-category-help">Erklärung für die Prüfer</label><textarea id="setting-category-help" maxlength="4000" rows="4">${E(c?.help||'')}</textarea><label for="setting-category-order">Reihenfolge</label><input id="setting-category-order" type="number" min="0" max="100000" value="${c?.order??defs.length}"><label for="setting-category-topics">Beispiele / Unteraufgaben (eine je Zeile)</label><textarea id="setting-category-topics" rows="5">${E((c?.topics||[]).join('\n'))}</textarea>${settingsType==='AP'?'<p class="callout">Neue Kategorien werden nicht automatisch zu gesetzlichen Prüfungsbereichen. Bei jeder Aufgabe muss die zuständige Stelle die konkrete Bereichszuordnung fachlich prüfen und begründen.</p>':''}`,btn('close','Abbrechen')+btn('settings-category-save','Thema speichern','primary',id||''));}
function saveSettingsCategory(id){const record=settingsRecord(),definition=L.resolveCatalog(db,settingsScope()).find(c=>c.id===id),patch={id:id||C.id('custom'),label:$('#setting-category-label').value.trim(),help:$('#setting-category-help').value.trim(),order:Number($('#setting-category-order').value),hidden:definition?.hidden||false,topics:$('#setting-category-topics').value.split('\n').map(x=>x.trim()).filter(Boolean)};record.categories=record.categories.filter(c=>c.id!==patch.id).concat(patch);saveSettingsRecord(record);}
function removeSettingsCategory(id){const record=settingsRecord(),c=L.resolveCatalog(db,settingsScope()).find(x=>x.id===id);if(!c)return;const referenced=db.tasks.some(t=>t.planningCategories?.includes(id))||db.patterns.some(p=>p.slots?.some(s=>s.categoryId===id)||p.categoryDefinitions?.some(c=>c.id===id))||db.exams.some(e=>e.pattern?.categoryDefinitions?.some(c=>c.id===id)||C.examEntries(e).some(i=>i.task.planningCategories?.includes(id)));const hard=c.origin==='custom'&&!referenced;if(!confirm(hard?'Dieses noch nicht verwendete eigene Thema endgültig entfernen?':'Dieses Thema für neue Prüfungen ausblenden? Vorhandene Aufgaben und Prüfungen bleiben erhalten.'))return;if(hard)record.categories=record.categories.filter(x=>x.id!==id);else record.categories=record.categories.filter(x=>x.id!==id).concat({...record.categories.find(x=>x.id===id),id,hidden:true});saveSettingsRecord(record);}
function restoreSettingsCategory(id){const record=settingsRecord();record.categories=record.categories.filter(x=>x.id!==id).concat({...record.categories.find(x=>x.id===id),id,hidden:false});saveSettingsRecord(record);}
function saveSettingsDefaults(){const record=settingsRecord();record.defaults={title:$('#settings-title').value.trim(),notes:$('#settings-notes').value,targetMinutes:$('#settings-minutes').value===''?null:Number($('#settings-minutes').value)};saveSettingsRecord(record);}

function scopeView(){return `<p class="eyebrow">1 · Prüfungsbereich wählen</p><h1>Welche Prüfung bereiten wir vor?</h1><p class="intro">Gärtner-Zwischenprüfung, Gärtner-Abschlussprüfung und Fachwerker-Abschlussprüfung haben getrennte Aufgaben und Prüfungsmuster.</p><div class="scope-types">${[['ZP','Zwischenprüfung','Grundlegende praktische Fertigkeiten'],['AP','Abschlussprüfung','Fachrichtungsbezogene Arbeitsaufgaben'],['FW_AP','Fachwerker · Abschlussprüfung','Gartenbaufachwerker: Gemüsebau und Zierpflanzenbau']].map(([id,title,sub])=>`<button class="scope-choice ${type===id?'selected':''}" data-action="choose-type" data-id="${id}"><span class="eyebrow">${id}</span><h2>${title}</h2><p>${sub}</p><strong>${L.scoped(db,id,fr||FR[0]).length? 'Prüfungsbereich öffnen →':'Fachrichtung wählen →'}</strong></button>`).join('')}</div>${type?`<h2 class="section-title">Fachrichtung der ${C.examTypeLabel(type)}</h2><div class="cards">${FR.filter(s=>C.examTypesFor(s).includes(type)).map(s=>{const ts=L.scoped(db,type,s);return `<button class="scope-choice" data-action="choose-specialty" data-id="${E(s)}"><h3>${E(s)}</h3><p>${ts.length} praktische Varianten · ${new Set(ts.map(t=>t.familyId)).size} Aufgabenfamilien</p><span class="tiny">${ts.length?'Prüfungsmuster und Kategorien ansehen →':'Noch kein praktischer Aufgabenbestand vorhanden'}</span></button>`;}).join('')}</div>`:''}${online?'<div class="callout"><strong>Zugänge für Arbeitsgruppen</strong>Lege einen Termin an und nutze „Gruppen & Einladungen“ für die befristeten Zugänge. Die erlaubten Prüfungsarten bestimmst du beim Bearbeiten des Termins.</div>':'<div class="callout warning"><strong>Lokaler Zugang der zuständigen Stelle</strong>Diese Offline-Datei hat keine getrennten Prüferkonten. Für befristete Gruppenzugänge den eingerichteten Online-Dienst verwenden.</div>'}`;}
function scopeHeading(step){return `<p class="eyebrow">${step} · ${C.examTypeLabel(type)}</p><h1>${E(fr)}</h1><div class="toolbar"><span class="badge ${type==='AP'?'blue':''}">${C.examTypeLabel(type)}</span>${btn('all-categories','Kategorien & Aufgaben','small')}<button class="small ghost" data-route="scope">Prüfungsbereich wechseln</button></div>`;}
function historyText(h){return h.unknown?'Nutzung unbekannt · vor Auswahl prüfen':`${h.confirmed?'Bestätigter Einsatz: '+h.confirmed:'Kein bestätigter Einsatztermin'}${h.sourceYear?' · jüngstes Quelldokument: '+h.sourceYear:''}`;}
function patternView(){if(type==='FW_AP'&&L.examRequirements({examType:type,specialty:fr}))return `${scopeHeading('Prüfungsaufbau')}${regulationStatus({examType:type,specialty:fr,items:[]})}<section class="panel"><h2>Vier praktische Aufgaben auswählen</h2><p>Die sieben Hauptaufgabengebiete helfen bei der Suche. Sie sind keine Pflichtquoten; mehrere Aufgaben dürfen zum selben Gebiet gehören. Insgesamt sind vier Aufgaben und 180 Minuten praktische Prüfungszeit erforderlich.</p>${fwTopicGuide({examType:type,specialty:fr})}<div class="toolbar">${btn('new-exam','Neue Prüfung erstellen','primary')}${btn('regulation-help','Verordnung & Erläuterungen')}</div></section>`;if(L.regulationProfile({examType:type,specialty:fr}))return regulationPatternView();const p=L.pattern(db,type,fr),zp=!!L.zwischenpruefungScope({examType:type,specialty:fr}),tasks=L.scoped(db,type,fr),unknown=tasks.filter(t=>L.classify(t).ids.includes('unassigned')).length;return `${scopeHeading('2 · Prüfungsmuster')}${fwTopicGuide({examType:type,specialty:fr})}<p class="intro">Das bestätigte Muster legt fest, wie viele Aufgaben jede Kategorie abdecken müssen. Neue Prüfungen übernehmen eine feste Kopie dieses Musters.</p><div class="callout ${p.status==='confirmed'?'':'warning'}"><strong>${p.status==='confirmed'?'Arbeitsmuster bestätigt':'Vorschlag aus dem vorhandenen Archiv'}</strong>${E(p.note||'')} ${unknown?`${unknown} Aufgaben haben noch keine eindeutige Kategorie.`:''}</div>${!L.categories(db,type,fr).length?'<p class="callout warning">Für diese Fachrichtung und Prüfungsart liegen noch keine auswertbaren Kategorien vor. Bitte passende Originalaufgaben ergänzen.</p>':''}${p.slots.some(s=>!L.categories(db,type,fr).some(c=>c.id===s.categoryId))?'<p class="callout warning">Das gespeicherte Muster enthält Kategorien außerhalb der belegten Fachrichtung und Prüfungsart. Beim erneuten Speichern werden nur die unten angebotenen Kategorien übernommen. Bestehende Prüfungskopien behalten ihr bisheriges Muster.</p>':''}<div class="panel"><div class="row between"><h2>Pflichtkategorien</h2><span class="badge">${type} · Version ${E(String(p.version||1))}</span></div><p class="tiny">${zp?'0 = nicht auswählen, 1 = eine Einzelaufgabe aus diesem Generalthema. Jedes Thema darf höchstens einmal vorkommen. Kombinationsaufgaben sind ausgeschlossen. Wähle genau drei Generalthemen; die Prüfung enthält genau drei praktische Aufgaben und höchstens 180 Minuten.':'0 = nicht Bestandteil des Musters. Kombinationsaufgaben können mehrere Kategorien zugleich abdecken. Anzahl und Vollständigkeit fachlich prüfen.'}</p>${zp?zwischenpruefungInfo({examType:type,specialty:fr}):type==='AP'?'<p class="tiny">Kategorien der Abschlussprüfung dieser Fachrichtung. Kategorienamen: Excel-Notenberechnung AP Sommer 2026, Blatt „Aufgaben“. Kategorien ohne Treffer haben noch keine zugeordneten Aufgaben. Die Excel-Liste legt keine Pflichtanzahl fest. Beim Speichern gelten die neuen Kategorien für dieses Arbeitsmuster; bestehende Prüfungskopien behalten ihren bisherigen Kategorienstand.</p>':''}${L.categories(db,type,fr).map(c=>{const ts=tasks.filter(t=>(!zp||L.eligibleZwischenpruefungTask(t))&&L.classify(t).ids.includes(c.id)),slot=p.slots.find(s=>s.categoryId===c.id),ys=[...new Set(ts.flatMap(years))].sort();return `<div class="pattern-row"><div><strong>${E(c.label)}</strong><p class="tiny">${ts.length} Varianten · ${new Set(ts.map(t=>t.familyId)).size} Familien · Quelljahre: ${ys.join(', ')||'keine Belege im Bestand'}</p></div><label>Anzahl<input data-slot-count="${c.id}" aria-label="Anzahl ${E(c.label)}" type="number" min="0" max="${zp?1:10}" step="1" value="${slot?.count||0}"></label></div>`;}).join('')}<div class="field"><label for="pattern-note">Hinweise zum Prüfungsmuster</label><textarea id="pattern-note">${E(p.note||'')}</textarea></div><div class="field"><label for="pattern-reviewer">Bestätigt durch (Name oder Kürzel)</label><input id="pattern-reviewer" value="${E(p.reviewedBy||'')}"></div><label class="check"><input id="pattern-confirm" type="checkbox" ${p.status==='confirmed'?'checked':''}>Die Pflichtkategorien und Anzahlen sind als Arbeitsgrundlage bestätigt.</label><div class="toolbar">${btn('save-pattern','Prüfungsmuster speichern','primary')}${btn('new-exam','Neue Prüfung nach diesem Muster')}</div></div>`;}
function savePattern(){const previous=L.pattern(db,type,fr),slots=$$('[data-slot-count]').map(x=>({categoryId:x.dataset.slotCount,count:Number(x.value)})).filter(x=>x.count!==0),confirmed=$('#pattern-confirm').checked,reviewedBy=$('#pattern-reviewer').value.trim();if(confirmed&&!reviewedBy)throw Error('Bitte Name oder Kürzel für die Musterbestätigung eintragen.');const p={...C.clone(previous),id:`pattern:${type}:${fr}`,examType:type,specialty:fr,slots,status:confirmed?'confirmed':'proposed',reviewedBy,note:$('#pattern-note').value.trim(),version:(previous.version||0)+1,updatedAt:C.now(),...(['AP','ZP'].includes(type)?{categoryCatalog:L.zwischenpruefungScope({examType:type,specialty:fr})?'zp-general-2026':'excel-ap-2026'}:{})};L.checkPattern(p);db.patterns=db.patterns.filter(x=>!(x.examType===type&&x.specialty===fr));db.patterns.push(p);changed();render();toast('Muster gespeichert. Bestehende Prüfungen behalten ihren bisherigen Musterstand.');}
const bankScopes=new Map();let bankScopeKey='catalog';
