function collectionView(){const archive=route==='archive';return `<section class="collection"><div class="collection-heading"><div><p class="eyebrow">Gesamter Aufgabenbestand</p><h1>Aufgaben & Archiv</h1></div>${uiPanel('collection-tools','Verwalten','<button data-route="import">Unterlagen einlesen</button><button data-route="settings">Themen & Grundeinstellungen</button><button data-route="scope">Prüfungsmuster & Zuordnungen</button>','collection-tools')}</div><nav class="collection-tabs" aria-label="Bestand durchsuchen"><button class="collection-tab ${!archive?'active':''}" data-route="catalog" aria-current="${!archive?'page':'false'}">${I.icon('library')}<span>Aufgaben</span></button><button class="collection-tab ${archive?'active':''}" data-route="archive" aria-current="${archive?'page':'false'}">${I.icon('archive')}<span>Alte Prüfungen</span></button></nav><p class="collection-intro">${archive?'Prüfungsarchiv: Originalunterlagen nach Jahr finden und erneut ausdrucken.':'Aufgabenbank: Aufgaben suchen, vergleichen und für neue Prüfungen verwenden.'}</p>${archive?archiveView(true):bankView(true)}</section>`;}
function bankView(embedded=false){const scoped=route==='bank',f=bankFilter(),facets=B.facets(db,f),results=bankResults(),all=B.scope(db,{...f,query:''}),ids=new Set(results.map(t=>t.id));bankSelection=new Set([...bankSelection].filter(id=>ids.has(id)));const visible=results.slice(0,limit),familyCount=new Set(results.map(t=>t.familyId)).size;
 return `${embedded?'':`<div class="bank-heading"><div><p class="eyebrow">${scoped?E(fr)+' · '+C.examTypeLabel(type):'Aufgabenbestand'}</p><h1>Aufgabenbank</h1></div>${btn('new-task','Aufgabe anlegen','primary')}</div>`}

 <section class="bank-filter-panel" aria-label="Aufgabenbank filtern"><div class="bank-search"><span aria-hidden="true">${I.icon('search')}</span><input id="bank-query" type="search" aria-label="Aufgabenbank durchsuchen" placeholder="Aufgabe, Pflanze, Stichwort oder Quelle suchen …" value="${E(f.query||'')}"></div><div class="bank-filter-grid">${scoped?'':bankControl('specialty','Fachrichtung',FR,'Alle Fachrichtungen')+bankControl('examType','Prüfungsart',[['ZP','Zwischenprüfung'],['AP','Abschlussprüfung'],['FW_AP','Fachwerker · Abschlussprüfung']],'Alle Prüfungsbereiche')}${bankControl('category','Prüfungskategorie',facets.categories.map(c=>[c.id,c.label]),'Alle passenden Kategorien')}</div><div class="toolbar bank-filter-tools">${btn('bank-advanced',bankAdvanced?'Weniger Filter ↑':'Weitere Filter ↓','ghost small')}<span class="tiny">${Object.entries(f).filter(([k,v])=>v&&k!=='sort'&&k!=='kind').length} Filter aktiv</span>${btn('bank-reset','Filter zurücksetzen','ghost small')}</div>${bankAdvanced?`<div class="bank-filter-grid advanced-filters">${bankControl('tag','Stichwort',facets.tags,'Alle Stichwörter')}${scoped?'':bankControl('kind','Bestandsteil',[['practical','Praktische Aufgaben'],['oral','Mündliche Aufgaben'],['other','Sonstige Unterlagen']],'Alle Bestandsteile')}${bankControl('family','Aufgabenfamilie',facets.families.map(x=>[x.id,x.title]))}${bankControl('review','Fachliche Prüfung',[['approved','Freigegeben'],['review','Noch prüfen']])}${bankControl('solution','Lösung',[['approved','Freigegeben'],['draft','Entwurf'],['missing','Fehlt']])}${bankControl('history','Nutzung der Familie',[['older2','Letzter Beleg mindestens 2 Jahre alt'],['older3','Letzter Beleg mindestens 3 Jahre alt'],['older5','Letzter Beleg mindestens 5 Jahre alt'],['confirmed','Mit bestätigtem Einsatz'],['unconfirmed','Ohne bestätigten Einsatz'],['unknown','Nutzung vollständig unbekannt']])}${bankControl('year','Quelljahr der Variante',facets.years)}${bankControl('source','Quelldokument',facets.sources.map(s=>[s.id,s.name]))}${bankControl('assets','Bilder / Anlagen',[['yes','Mit Anlagen'],['no','Ohne Anlagen']])}${bankControl('flags','Übernahme prüfen',[['yes','Mit offenen Hinweisen'],['no','Ohne Hinweise']])}${bankControl('revisions','Revisionen',[['all','Aktuelle und frühere'],['old','Nur frühere']],'Nur aktuelle')}${[['points','Punkte'],['minutes','Minuten']].map(([k,l])=>`<div class="field"><label>${l}</label><div class="range-fields"><input type="number" min="0" step="any" data-bank-filter="${k}Min" aria-label="${l} mindestens" placeholder="von" value="${E(f[k+'Min']||'')}"><span>–</span><input type="number" min="0" step="any" data-bank-filter="${k}Max" aria-label="${l} höchstens" placeholder="bis" value="${E(f[k+'Max']||'')}"></div></div>`).join('')}</div><p class="tiny">„Letzter Beleg“ berücksichtigt erfasste Einsätze dieser oder einer ähnlichen Aufgabe und die Jahre der Vorlagen. Fehlende Angaben bedeuten nicht „nie verwendet“. Zahlenfilter schließen unbekannte Werte aus.</p>`:''}</section>
 <div class="bank-result-tools"><div><strong>${results.length} Treffer</strong><span class="tiny"> · ${familyCount} ähnliche Aufgabengruppen${bankSelection.size?' · '+bankSelection.size+' ausgewählt':''}</span></div>${uiPanel('bank-options','Ansicht & Export'+(bankSelection.size?' · '+bankSelection.size+' ausgewählt':''),`<div class="toolbar">${bankControl('sort','Sortierung',[['rotation','Lange nicht verwendet zuerst'],['title','Titel A–Z'],['source-new','Neueste Quelljahre zuerst'],['points','Punkte aufsteigend'],['minutes','Minuten aufsteigend'],['updated','Zuletzt bearbeitet']],'Rotation (älteste zuerst)')}<div class="view-switch" aria-label="Darstellung">${btn('bank-layout','▦ Karten',bankLayout==='cards'?'primary small':'small','cards')}${btn('bank-layout','☷ Liste',bankLayout==='list'?'primary small':'small','list')}</div></div>
 ${!isGroup?`<div class="bank-selection-bar"><div class="toolbar">${btn('bank-select-all','Alle '+results.length+' Treffer auswählen','small')}${btn('bank-select-none','Auswahl aufheben','ghost small')}</div>${btn('bank-export','↓ '+(bankSelection.size?bankSelection.size+' ausgewählte Aufgaben':'Treffer')+' exportieren','primary')}</div>`:''}${btn('new-task','Eigene Aufgabe anlegen','wide')}`,'bank-options')}</div>

 ${!results.length?`<div class="panel empty"><h2>Keine passenden Aufgaben</h2><p>${all.length?'Lockern Sie die Filter oder verwenden Sie einen anderen Suchbegriff.':'Für diesen Bereich fehlen noch passende Aufgaben im Bestand.'}</p>${btn('bank-reset','Filter zurücksetzen')}${isGroup?'':'<button data-route="import">Unterlagen ergänzen</button>'}</div>`:bankLayout==='cards'?`<div class="bank-cards">${visible.map(bankCard).join('')}</div>`:`<div class="bank-table-wrap"><table class="bank-table"><thead><tr>${isGroup?'':'<th>Auswahl</th>'}<th>Aufgabe / Familie</th><th>Prüfungsbereich</th><th>Punkte / Zeit</th><th>Bearbeitung</th><th></th></tr></thead><tbody>${visible.map(t=>`<tr>${isGroup?'':`<td>${bankCheckbox(t)}</td>`}<td><button class="text-button" data-action="detail" data-id="${E(t.id)}">${E(t.title)}</button><p class="tiny">${E(family(t.familyId)?.title||'')}<br>${E(B.historyLabel(L.history(db,t)))}</p></td><td>${E(t.specialty)}<br><span class="badge">${t.examType}</span><p class="tiny">${L.labels(t,undefined,L.projectContext(db,t)).map(E).join(' · ')}</p></td><td>${E(C.pointsLabel(t))}<br>${num(t.minutes,' Min.')}</td><td><span class="badge ${t.reviewStatus==='approved'?'':'amber'}">${t.reviewStatus==='approved'?'Freigegeben':'Noch prüfen'}</span><p class="tiny">${E(solutionLabel(t))}</p></td><td>${bankActions(t)}</td></tr>`).join('')}</tbody></table></div>`}
 ${results.length>limit?`<div class="bank-pagination"><p class="tiny">${Math.min(limit,results.length)} von ${results.length} angezeigt · Export und Auswahl beziehen sich auf alle Treffer.</p>${btn('more','Weitere Aufgaben anzeigen','wide')}</div>`:''}`;
}
function bankCheckbox(t){return `<label class="bank-check"><input type="checkbox" data-bank-select="${E(t.id)}" ${bankSelection.has(t.id)?'checked':''} aria-label="Aufgabe auswählen: ${E(t.title)}"><span class="sr-only">Auswählen</span></label>`;}
function taskAddControl(t,label='+ Zur Prüfung',cls='small'){const e=current(),issue=e?.status==='used'?'Bereits eingesetzte Prüfung zuerst duplizieren.':e&&t.kind==='practical'?L.structureSelectionIssue(e,t)||(!L.selectedTask(t,e)?'Wähle zuerst das passende Thema im ersten Schritt aus.':null):null,control=btn('add',label,cls,t.id);return issue?control.replace('>',' disabled title="'+E(issue)+'">')+`<span class="tiny paper-selection-issue">${E(issue)}</span>`:control;}
function bankActions(t){return btn('detail','Aufgabe ansehen','small',t.id)+btn('bank-family','Varianten','ghost small',t.id)+(route==='bank'&&!t.supersededBy?taskAddControl(t):'');}
function bankCard(t){const graphic=t.assetLinks.find(l=>l.role!=='letterhead'&&l.audience==='candidate'&&/^image\/(png|jpeg|webp)$/.test(asset(l.assetId)?.mime||'')),a=graphic&&asset(graphic.assetId);return `<article class="bank-card ${bankSelection.has(t.id)?'selected':''}" ${route==='bank'?'draggable="true"':''} data-drag-task="${E(t.id)}"><div class="bank-card-head"><span class="badge ${t.examType==='AP'?'blue':''}">${E(C.examTypeLabel(t.examType))} · ${E(t.specialty)}</span>${isGroup?'':bankCheckbox(t)}</div>${a?`<div class="bank-thumbnail">${P.image(a,graphic.caption||a.name)}</div>`:''}<p class="bank-category">${L.labels(t,undefined,L.projectContext(db,t)).map(E).join(' · ')}</p><h2><button class="text-button" data-action="detail" data-id="${E(t.id)}">${E(t.title)}</button></h2><p class="excerpt">${E(t.text.slice(0,350))}</p><div class="tags">${t.tags.slice(0,4).map(tag=>`<span class="tag">${E(tag)}</span>`).join('')}${t.supersededBy?'<span class="badge amber">Frühere Revision</span>':''}</div><div class="bank-card-facts"><span>${E(C.pointsLabel(t))}</span><span>${(t.minutes==null?'Bearbeitungszeit offen':t.minutes+' Min. Bearbeitungszeit')}</span><span>${t.assetLinks.filter(l=>l.audience!=='source'&&!['letterhead','brand-font'].includes(l.role)).length} Anlagen</span></div><div class="bank-review"><span class="badge ${t.reviewStatus==='approved'?'':'amber'}">${t.reviewStatus==='approved'?'Aufgabe freigegeben':'Aufgabe noch prüfen'}</span><span class="badge ${t.solutionStatus==='approved'?'':'gray'}">${E(solutionLabel(t))}</span></div><p class="bank-history">${E(B.historyLabel(L.history(db,t)))}</p><div class="bank-card-actions">${bankActions(t)}</div></article>`;}
function bankExportDialog(){if(isGroup)throw Error('Exporte sind der zuständigen Stelle vorbehalten.');const ts=bankResults().filter(t=>!bankSelection.size||bankSelection.has(t.id));if(!ts.length)throw Error('Bitte zuerst passende Aufgaben suchen.');openModal('Aufgabenbank exportieren',`<p class="eyebrow">${ts.length} ${bankSelection.size?'ausgewählte Aufgaben':'gefilterte Aufgaben'}</p><h3>Welches Format benötigen Sie?</h3><div class="export-choices"><label><input type="radio" name="bank-format" value="zip" checked><strong>Druckbarer Fragenkatalog · ZIP</strong><span>Aufgaben als HTML mit Bildern; PDF-Anlagen separat. Im Browser öffnen und drucken oder als PDF speichern.</span></label><label><input type="radio" name="bank-format" value="csv"><strong>Tabelle · CSV für Excel</strong><span>Metadaten, Aufgabenstellungen und optional Lösungen. Keine Bilddateien.</span></label><label><input type="radio" name="bank-format" value="json"><strong>Strukturierte Dokumentation · JSON</strong><span>Ausgewählte Aufgaben, Historienangaben und verknüpfte Anlagen. Kein importierbares Projektbackup.</span></label></div><label class="check"><input type="checkbox" id="bank-solutions">Lösungen, Erwartungshorizonte und Prüferanlagen einschließen</label><p class="callout warning">Die Datei ist eine vertrauliche Kopie auf Ihrem Gerät. Sie bleibt nach dem Sitzungsschluss lesbar. Vollständige Originaldokumente sind in diesem Auszug nicht enthalten.</p><p class="tiny">Für eine vollständige Sicherung verwenden Sie „Projekt sichern“. Fertige Prüfungen mit passender Lösung werden im jeweiligen Prüfungsentwurf exportiert.</p>`,btn('close','Abbrechen')+btn('bank-export-create','Export erstellen','primary'));}
async function exportBank(){if(isGroup)throw Error('Exporte sind der zuständigen Stelle vorbehalten.');const outputDb=C.clone(db);const format=$('[name="bank-format"]:checked')?.value,solutions=$('#bank-solutions').checked,ts=bankResults().filter(t=>!bankSelection.size||bankSelection.has(t.id)).map(t=>outputDb.tasks.find(x=>x.id===t.id));if(!ts.length)throw Error('Die Auswahl ist leer.');if(online){await flush();await online.request('/api/export');}if(format!=='csv')await requireAssets(taskAssetIds(ts,solutions),outputDb);const name='Pruefungswerkstatt-Aufgabenbank-'+new Date().toISOString().slice(0,10);if(format==='csv'){download(name+'.csv',B.csv(outputDb,ts,solutions),'text/csv;charset=utf-8');closeModal();toast('CSV mit '+ts.length+' Aufgaben erstellt.');return;}if(format==='json'){download(name+'.json',JSON.stringify(B.package(outputDb,ts,solutions),null,2));closeModal();toast('JSON-Dokumentation erstellt.');return;}const z=new JSZip();z.file('Fragenkatalog.html',B.document(outputDb,ts,solutions));for(const file of P.attachments({items:ts.map(task=>({task}))},outputDb,solutions)){const a=outputDb.assets.find(a=>a.id===file.assetId);z.file(file.path,a.data,{base64:true});}z.file('LESEN.txt','Vertraulicher Auszug aus der Pruefungswerkstatt-Aufgabenbank.\nFragenkatalog.html im Browser öffnen und Drucken / als PDF speichern wählen.\n'+(solutions?'Enthält Lösungen und Prüferanlagen. Nicht an Prüflinge weitergeben.':'Keine Lösungsfelder oder Prüferanlagen enthalten. Aufgabeninhalte vor Weitergabe fachlich prüfen.')+'\nSeparate Anlagen ergänzen; Druckmaßstab prüfen. Kein Projektbackup.\n');if(online)await online.request('/api/export');offerDownload(await z.generateAsync({type:'blob',compression:'DEFLATE'}),name+'.zip',ts.length+' Aufgaben wurden als druckbarer Fragenkatalog zusammengestellt.');}
function wireBank(){const q=$('#bank-query');q?.addEventListener('input',()=>{bankFilters.query=q.value;bankSelection.clear();limit=24;const pos=q.selectionStart;render();$('#bank-query')?.focus();try{$('#bank-query')?.setSelectionRange(pos,pos);}catch{}});for(const el of $$('[data-bank-filter]'))el.addEventListener('change',()=>{const key=el.dataset.bankFilter;if(route==='bank'&&key==='category')category=el.value;else bankFilters[key]=el.value;if(['specialty','examType','kind','revisions'].includes(key))for(const child of ['category','tag','family','source','year'])bankFilters[child]='';bankSelection.clear();limit=24;render();});for(const el of $$('[data-bank-select]'))el.addEventListener('change',()=>{if(el.checked)bankSelection.add(el.dataset.bankSelect);else bankSelection.delete(el.dataset.bankSelect);render();});}
