 const yearSections=years?years.map(([y,list])=>{const used=list.filter(x=>L.history(db,x.pick).confirmed).length,names=y==='none'?[]:[...new Set(db.sources.filter(s=>s.year===y&&list.some(x=>x.ts.some(t=>t.sourceIds.includes(s.id)))).map(s=>s.name))];return `<section class="archive-year" aria-label="${y==='none'?'Ohne Quelljahr':'Quelljahr '+y}"><h3 class="archive-year-head"><span class="archive-year-label">${y==='none'?'Ohne Quelljahr':y}</span><span class="archive-year-meta">${list.length} ${list.length===1?'Aufgabe':'Aufgaben'}${used?` · ${used} seitdem eingesetzt`:''}</span></h3>${names.length?`<p class="archive-year-sources">Aus ${names.slice(0,3).map(E).join(' · ')}${names.length>3?` und ${names.length-3} weiteren`:''}</p>`:''}<div class="paper-task-list">${list.map(x=>card(x.ts,x.pick)).join('')}</div></section>`;}).join(''):'';
 const layoutSwitch=`<div class="layout-switch" role="group" aria-label="Darstellung der Aufgaben">${[['grid','Liste'],['years','Archiv nach Jahr']].map(([v,l])=>`<button class="small ${paperLayout===v?'primary':''}" data-action="paper-layout" data-id="${v}" aria-pressed="${paperLayout===v}">${l}</button>`).join('')}</div>`;
 const count=grouped.size,scopeLabel=foreign&&scopes.find(([v])=>v===paperScope)?.[1];
 const library=`<aside class="paper-library" aria-label="Aufgaben auswählen"><div class="library-top"><div class="library-head"><div class="library-title"><h2>Aufgaben auswählen</h2></div><div class="library-actions">${!used&&!forbidden('new-task')?`<button class="small" data-action="new-task" title="Neue praktische Aufgabe anlegen. Sie wird in der Fragenbank gespeichert und, wenn möglich, direkt in diese Prüfung übernommen.">${I.icon('plus')}<span>Eigene Aufgabe</span></button>`:''}${!used&&aiDraftAvailable()?`<button class="small" data-action="ai-draft-open" title="Vorschlag einfügen oder als Word-/Textdatei laden: Der KI-Assistent erstellt einen Aufgabenentwurf mit Rückfragen.">${I.icon('idea')}<span>Aus Vorschlag (KI)</span></button>`:''}${!used&&editorMode==='klassisch'?`<button class="primary small" data-action="suggest" title="Sucht passende Aufgaben für noch offene Themen. Länger nicht verwendete Aufgaben zuerst; du siehst die Vorschläge vor der Übernahme.">${I.icon('idea')}<span>Aufgaben automatisch ergänzen</span></button>`:''}</div></div>${filters}</div>${foreign?`<p class="library-scope-note"><strong>${E(scopeLabel||'Anderer Bereich')}</strong> „Für diese Prüfung übernehmen“ legt eine Kopie als Entwurf an. Die Herkunft bleibt vermerkt; die fachliche Freigabe folgt wie bei jeder neuen Aufgabe. ${btn('paper-scope-clear','Zurück zu „'+C.examTypeLabel(e.examType)+'“','ghost small')}</p>`:`<div class="library-themes"><div class="library-themes-label"><strong>Thema</strong>${paperInfo('Themen',themeInfo)}</div>${categories}</div>`}${fwTopicGuide(e)}<div class="library-results">${layoutSwitch}<strong class="library-count">${count} ${foreign?(count===1?'Aufgabe':'Aufgaben')+' zum Übernehmen':count===1?'passende Aufgabe':'passende Aufgaben'}</strong>${field('paper-sort','Reihenfolge',[['rotation','Lange nicht verwendet'],['title','Titel A–Z'],['points','Wenige Punkte zuerst']],paperSort,'Die Auswahl berücksichtigt frühere Einsätze und Quelljahre. Ohne Jahresangabe bleibt die Nutzung unbekannt.')}</div>${years?yearChips+(yearSections||`<div class="paper-no-results archive-empty"><strong>Keine Aufgabe aus diesem Jahrgang</strong><p>Wähle ein anderes Jahr oder entferne einen Filter.</p>${btn('paper-reset','Alle Aufgaben anzeigen','small')}</div>`):`<div class="paper-task-list">${cards||`<div class="paper-no-results"><strong>Keine Aufgabe gefunden</strong><p>${foreign?'Ändere den Suchbegriff oder wähle eine andere Prüfungsart.':'Wähle ein anderes Thema oder entferne einen Filter.'}</p>${btn('paper-reset','Alle Aufgaben anzeigen','small')}</div>`}</div>`}${foreign||altTarget()?'':morePanel(e,count)}</aside>`;
