// The checklist follows the sheet: the card on top belongs to the task (or missing task) currently in view.
function checklistTarget(e,gaps,oralGap){const ids=[...C.examEntries(e,{alternatives:true}).map(i=>i.id),...(paperSolutions?[]:gaps.map(g=>g.id)),...(oralGap&&!paperSolutions?['oral-gap']:[])];return ids.includes(checklistFocus)?checklistFocus:ids[0]||null;}
