 const t=entry.task,practical=entry.component==='practical'&&(t.kind===undefined||t.kind==='practical');let cat='';try{cat=entry.component==='oral'?'':taskCategory(t,e);}catch{cat='';}
 const act=(action,label,arg)=>used?'':btn(action,label,'small',arg),lines=s=>String(s||'').split('\n').filter(x=>x.trim()).length;
 const rows=[{done:!!t.text?.trim(),title:'Aufgabenstellung',detail:t.text?.trim()?'auf dem Blatt':'fehlt noch',fix:act('required-field','Schreiben',JSON.stringify([id,'text']))},
  {done:t.points>0&&t.minutes>0,title:'Punkte & Zeit',detail:`${t.points>0?t.points+' Punkte':'Punkte fehlen'} · ${t.minutes>0?t.minutes+' Min.':'Zeit fehlt'}`,fix:act('details-open','Eintragen',id)},
  ...(practical?[{done:!!t.materials?.text?.trim(),title:'Materialliste',detail:t.materials?.text?.trim()?`${lines(t.materials.text)} ${lines(t.materials.text)===1?'Eintrag':'Einträge'}`:'fehlt noch',fix:act('details-open','Eintragen',id)}]:[])];
