 if(e.examType!==fields.examType||e.specialty!==fields.specialty){delete e.regulationReview;delete e.regulationReviewKey;delete e.selectedCategoryIds;delete e.oralRequirementVersion;delete e.materialRequirementVersion;const policy=C.newExam(fields);if(policy.oralRequirementVersion)e.oralRequirementVersion=policy.oralRequirementVersion;if(policy.materialRequirementVersion)e.materialRequirementVersion=policy.materialRequirementVersion;e.workflowStep=1;}
