   if(el.dataset.dropRemove!==undefined)return;
   if(s?.same){rejectDrop(el,'Diese Aufgabe ist bereits in der Prüfung.');return;}
   // Same family or an occupied theme (ZP): dropping replaces, asks first and can be undone.
